def delete_node(root, key):
    if not root:
        return None
    if key < root.val:
        root.left = delete_node(root.left, key)
    elif key > root.val:
        root.right = delete_node(root.right, key)
    else:
        if not root.left:
            return root.right                              # 0 or 1 child (right)
        if not root.right:
            return root.left                                # 1 child (left)
        successor = root.right
        while successor.left:                                 # find in-order successor
            successor = successor.left
        root.val = successor.val                                # overwrite value
        root.right = delete_node(root.right, successor.val)      # remove the successor's original spot
    return root

