    if (key < root->val) root->left = deleteNode(root->left, key);
    else if (key > root->val) root->right = deleteNode(root->right, key);
    else {
        if (!root->left) return root->right;                                   // 0 or 1 child (right)
        if (!root->right) return root->left;                                     // 1 child (left)
        TreeNode* successor = root->right;
        while (successor->left) successor = successor->left;                       // find in-order successor
        root->val = successor->val;                                                  // overwrite value
        root->right = deleteNode(root->right, successor->val);                        // remove successor's original spot
    }
    return root;
}
